 <!DOCTYPE html>
 <html lang="en">
 <head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>IRONLINE // Sector 7 Perimeter</title>
+<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3E%3Crect width='16' height='16' fill='%230d1110'/%3E%3Ccircle cx='8' cy='8' r='5' fill='none' stroke='%239ff5c3' stroke-width='2'/%3E%3C/svg%3E">
 <style>
   :root{
     --bg:#0d1110; --panel:#141a17; --grid:#1e2a24;
     --phos:#9ff5c3; --phos-dim:#5d8a71; --amber:#ffc857; --red:#ff5a5a;
     --ink:#d7e4da;
   }
   *{box-sizing:border-box;margin:0;padding:0}
   body{background:var(--bg);color:var(--ink);font-family:"Consolas","SF Mono",Menlo,monospace;
     display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:16px;
     background-image:radial-gradient(ellipse at 50% 0%,#18211c 0%,#0d1110 60%);}
   header{width:960px;max-width:96vw;display:flex;justify-content:space-between;align-items:center;
     background:var(--panel);border:1px solid #2a3a31;border-bottom:3px solid var(--phos-dim);
     padding:8px 14px;letter-spacing:2px;font-size:13px;}
   header .title{color:var(--phos);font-weight:bold}
   header .sub{color:var(--phos-dim);font-size:11px}
   #wrap{position:relative;width:960px;max-width:96vw;}
   canvas{width:100%;display:block;background:#0f1512;border:1px solid #2a3a31;cursor:crosshair;
     image-rendering:auto;}
