   .card .label{color:var(--phos-dim);font-size:10px;letter-spacing:2px;}
   .bar{height:10px;background:#0a0d0c;border:1px solid #2a3a31;margin-top:5px;position:relative}
   .bar>i{display:block;height:100%;transition:width .12s}
   #hpFill{background:linear-gradient(90deg,#57d98a,#9ff5c3);width:100%}
   #hpFill.low{background:linear-gradient(90deg,#ff5a5a,#ffc857)}
   #ammoFill{background:var(--amber);width:100%}
   #controlsRow{width:960px;max-width:96vw;display:flex;gap:8px;margin-top:8px;align-items:center}
