 <body>
 <header>
   <div><span class="title">IRONLINE</span> <span class="sub">// SECTOR 7 PERIMETER — OP: DUSTWALL</span></div>
   <div class="sub" id="clock">T+00:00</div>
 </header>
 <div id="wrap">
   <canvas id="game" width="960" height="600"></canvas>
   <div id="scan"></div>
   <div id="overlay">
     <div class="box">
       <h1 id="ovTitle">MISSION COMPLETE</h1>
       <p id="ovSub"></p>
       <div class="stats" id="ovStats"></div>
       <button id="btnRestart">↻ REDEPLOY [R]</button>
     </div>
   </div>
 </div>
 <div id="hud">
   <div class="card"><div class="label">OPERATOR INTEGRITY</div><div class="bar"><i id="hpFill"></i></div><div id="hpText">100 HP</div></div>
   <div class="card"><div class="label">MAG / RESERVE ∞</div><div class="bar"><i id="ammoFill"></i></div><div id="ammoText">30 / ∞ — [R] RELOAD</div></div>
   <div class="card"><div class="label">HOSTILES REMAINING</div><div style="font-size:22px;color:var(--amber)" id="foeText">12</div><div id="waveText" style="color:var(--phos-dim);font-size:11px">WAVE 1/1 — HOLD THE PAD</div></div>
 </div>
 <div id="controlsRow">
   <button id="btnStart">▶ START OP</button>
   <button id="btnRestart2">↻ RESTART [R]</button>
   <div class="hint"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> / arrows move &nbsp;·&nbsp; mouse aims &nbsp;·&nbsp; click / hold fires &nbsp;·&nbsp; <kbd>R</kbd> reload &amp; restart &nbsp;·&nbsp; <kbd>P</kbd> pause</div>
 </div>

 <script>
 (()=>{ "use strict";
 const W=960,H=600,ARENA={x:28,y:28,w:W-56,h:H-56};
 const cvs=document.getElementById('game'),ctx=cvs.getContext('2d');
 const hpFill=document.getElementById('hpFill'),hpText=document.getElementById('hpText');
 const ammoFill=document.getElementById('ammoFill'),ammoText=document.getElementById('ammoText');
 const foeText=document.getElementById('foeText'),clockEl=document.getElementById('clock');
 const overlay=document.getElementById('overlay'),ovTitle=document.getElementById('ovTitle'),
       ovSub=document.getElementById('ovSub'),ovStats=document.getElementById('ovStats');

 /* ---------- audio (procedural, no assets) ---------- */
 let AC=null;function ac(){if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();}if(AC.state==='suspended')AC.resume();return AC;}
 function blip(freq,dur,type='square',vol=.12,slide=0){try{const a=ac(),o=a.createOscillator(),g=a.createGain();
   o.type=type;o.frequency.setValueAtTime(freq,a.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,freq+slide),a.currentTime+dur);
   g.gain.setValueAtTime(vol,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+dur);
   o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+dur);}catch(e){}}
 function noise(dur=.2,vol=.2,low=400){try{const a=ac(),b=a.createBuffer(1,a.sampleRate*dur,a.sampleRate),d=b.getChannelData(0);
   for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);
   const s=a.createBufferSource();s.buffer=b;const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=low;
   const g=a.createGain();g.gain.value=vol;s.connect(f).connect(g).connect(a.destination);s.start();}catch(e){}}
 const SFX={
   shoot(){blip(880,.07,'square',.06,-500);noise(.06,.10,3000);},
   dry(){blip(180,.08,'square',.08);},
   reload(){blip(300,.09,'square',.09);setTimeout(()=>blip(520,.09,'square',.09),120);},
   hit(){blip(320,.06,'sawtooth',.10,-140);},
   kill(){noise(.3,.25,900);blip(140,.3,'sawtooth',.12,-90);},
   hurt(){blip(110,.25,'sawtooth',.2,-40);noise(.2,.2,500);},
   pickup(){blip(660,.1,'sine',.1,220);},
   win(){[523,659,784,1046].forEach((f,i)=>setTimeout(()=>blip(f,.22,'triangle',.14),i*150));},
   lose(){[330,262,196,131].forEach((f,i)=>setTimeout(()=>blip(f,.3,'sawtooth',.12),i*180));},
   spawn(){blip(220,.12,'sawtooth',.05,110);}
 };

 /* ---------- state ---------- */
 const MAG=30,RELOAD_T=1.1;
 let state='menu',kills=0,shots=0,timeAlive=0,shake=0,flashRed=0,muzzle=0;
 let player,bullets,enemies,parts,pickups,floaters,spawnQueue,spawnT;
 const keys={};let mouse={x:W/2,y:H/3,down:false};

 function reset(){
   player={x:W/2,y:H/2+80,r:13,hp:100,maxHp:100,angle:0,speed:235,mag:MAG,reloading:0,fireCd:0,inv:0,alive:true};
   bullets=[];enemies=[];parts=[];pickups=[];floaters=[];
   kills=0;shots=0;timeAlive=0;shake=0;flashRed=0;
   // short wave: 12 hostiles, 3 original classes
   const wave=[
     {t:'jackal',n:5},{t:'trooper',n:5},{t:'bulwark',n:2}
   ];
   spawnQueue=[];wave.forEach(g=>{for(let i=0;i<g.n;i++)spawnQueue.push(g.t);});
   // shuffle lightly so classes interleave
   spawnQueue.sort(()=>Math.random()-.5);
   spawnT=0.5;state='play';hideOverlay();SFX.reload();
 }
 function spawnEnemy(type){
   // spawn on arena edge away from player
   let x,y,tries=0;
   do{const side=(Math.random()*4)|0;
     if(side===0){x=ARENA.x+20+Math.random()*(ARENA.w-40);y=ARENA.y+20;}
     else if(side===1){x=ARENA.x+20+Math.random()*(ARENA.w-40);y=ARENA.y+ARENA.h-20;}
     else if(side===2){x=ARENA.x+20;y=ARENA.y+20+Math.random()*(ARENA.h-40);}
     else{x=ARENA.x+ARENA.w-20;y=ARENA.y+20+Math.random()*(ARENA.h-40);}
     tries++;
   }while(tries<12&&Math.hypot(x-player.x,y-player.y)<260);
   const base={x,y,vx:0,vy:0,hitT:0,kbx:0,kby:0,atkCd:0,wob:Math.random()*6.28};
   if(type==='jackal')enemies.push({...base,kind:'JACKAL',type,hp:30,maxHp:30,r:11,speed:150,dmg:8,score:100,col:'#e0a458'});
   else if(type==='trooper')enemies.push({...base,kind:'TROOPER',type,hp:65,maxHp:65,r:14,speed:95,dmg:14,score:200,col:'#e06a5a'});
   else enemies.push({...base,kind:'BULWARK',type,hp:160,maxHp:160,r:20,speed:52,dmg:22,score:400,col:'#c44be0'});
   burst(x,y,8,'#ffc857',160);SFX.spawn();
   addFloat(x,y-18,'CONTACT','warn');
 }

 /* ---------- fx helpers ---------- */
 function burst(x,y,n,col,spd=220){for(let i=0;i<n;i++){const a=Math.random()*6.28,s=spd*(.3+Math.random()*.9);
   parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.4+Math.random()*.4,t:0,col,r:1+Math.random()*3});}}
 function addFloat(x,y,txt,cls=''){floaters.push({x,y,txt,t:0,cls});}
 function damagePlayer(d){if(player.inv>0||state!=='play')return;player.hp-=d;player.inv=.35;flashRed=1;shake=Math.min(14,shake+6);
   SFX.hurt();burst(player.x,player.y,10,'#ff5a5a',260);
   if(player.hp<=0){player.hp=0;player.alive=false;gameOver(false);}}
 function gameOver(win){
   state=win?'win':'lose';
   if(win){SFX.win();burst(player.x,player.y,40,'#9ff5c3',320);}
   else{SFX.lose();burst(player.x,player.y,46,'#ff5a5a',340);}
   const mm=String((timeAlive/60)|0).padStart(2,'0'),ss=String((timeAlive|0)%60).padStart(2,'0');
   const acc=shots?Math.round(100*kills/Math.max(1,shots)):0;
   ovTitle.textContent=win?'MISSION COMPLETE':'OPERATOR DOWN';
   ovTitle.className=win?'win':'lose';
-  ovSub.innerHTML=win?'Sector 7 pad held. All <b style="color:#9ff5c3">12 hostiles</b> neutralized. Dustwall holds.':'Your operator was neutralized with hostiles still active.<br>Press <kbd>R</kbd> or hit REDEPLOY to try again.';
+  ovSub.innerHTML=win?`Sector 7 pad held. All <b style="color:#9ff5c3">${kills} hostiles</b> neutralized. Dustwall holds.`:'Your operator was neutralized with hostiles still active.<br>Press <kbd>R</kbd> or hit REDEPLOY to try again.';
   ovStats.textContent=`KILLS ${kills}/12 · TIME T+${mm}:${ss} · SHOTS ${shots}`;
+  // refresh HUD immediately so end-state screens never show stale bars
+  hpFill.style.width=(player.hp)+'%';hpFill.classList.toggle('low',player.hp<=35);
+  hpText.textContent=`${Math.max(0,Math.ceil(player.hp))} HP`;
+  ammoFill.style.width=(player.mag/MAG*100)+'%';
+  ammoText.textContent=player.reloading>0?'— RELOADING… —':`${player.mag} / ∞ — [R] RELOAD`;
+  foeText.textContent=`${12-kills}`;
   setTimeout(showOverlay,win?600:900);
 }
 function showOverlay(){overlay.classList.add('show');}
 function hideOverlay(){overlay.classList.remove('show');}

 /* ---------- input ---------- */
 addEventListener('keydown',e=>{
   const k=e.key.toLowerCase();keys[k]=true;
   if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();
   if(k==='r'){ac();if(state==='play'){if(player&&player.mag<MAG&&player.reloading<=0){player.reloading=RELOAD_T;SFX.reload();}}else{reset();}}
   if(k==='p'&&state==='play')state='pause';
   else if(k==='p'&&state==='pause')state='play';
   if(k==='enter'&&(state==='win'||state==='lose'||state==='menu')){ac();reset();}
 });
 addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
 cvs.addEventListener('mousemove',e=>{const r=cvs.getBoundingClientRect();
   mouse.x=(e.clientX-r.left)*(W/r.width);mouse.y=(e.clientY-r.top)*(H/r.height);});
 cvs.addEventListener('mousedown',e=>{ac();mouse.down=true;
   if(state==='menu')reset();});
 addEventListener('mouseup',()=>mouse.down=false);
 cvs.addEventListener('contextmenu',e=>e.preventDefault());
 document.getElementById('btnStart').onclick=()=>{ac();reset();};
 document.getElementById('btnRestart').onclick=()=>{ac();reset();};
 document.getElementById('btnRestart2').onclick=()=>{ac();reset();};

 /* ---------- update ---------- */
 let last=performance.now();
 function loop(now){
   let dt=Math.min(.033,(now-last)/1000);last=now;
   if(state==='play')update(dt);
   render();
-  requestAnimationFrame(loop);
+// debug/verify hook (harmless in production)
+window.IRONLINE={get state(){return state;},get kills(){return kills;},reset,
+  win(){if(state==='play')gameOver(true);},  lose(){if(player){player.inv=0;damagePlayer(9999);}if(state==='play')gameOver(false);}};
+requestAnimationFrame(loop);
 }
 function update(dt){
   timeAlive+=dt;
   // clock
   const mm=String((timeAlive/60)|0).padStart(2,'0'),ss=String((timeAlive|0)%60).padStart(2,'0');
   clockEl.textContent=`T+${mm}:${ss}`;
   // spawning: max 5 alive at once
   if(spawnQueue.length&&enemies.length<5){spawnT-=dt;if(spawnT<=0){spawnEnemy(spawnQueue.shift());spawnT=.7;}}
   // movement
   let mx=((keys['d']||keys['arrowright'])?1:0)-((keys['a']||keys['arrowleft'])?1:0);
   let my=((keys['s']||keys['arrowdown'])?1:0)-((keys['w']||keys['arrowup'])?1:0);
   if(mx&&my){mx*=.7071;my*=.7071;}
   player.x=Math.min(ARENA.x+ARENA.w-player.r,Math.max(ARENA.x+player.r,player.x+mx*player.speed*dt));
   player.y=Math.min(ARENA.y+ARENA.h-player.r,Math.max(ARENA.y+player.r,player.y+my*player.speed*dt));
   player.angle=Math.atan2(mouse.y-player.y,mouse.x-player.x);
   if(player.inv>0)player.inv-=dt;
   if(player.fireCd>0)player.fireCd-=dt;
   if(player.reloading>0){player.reloading-=dt;if(player.reloading<=0){player.mag=MAG;}}
   muzzle=Math.max(0,muzzle-dt*6);shake=Math.max(0,shake-dt*30);flashRed=Math.max(0,flashRed-dt*2.2);
   // firing
   if((mouse.down||keys[' '])&&player.fireCd<=0&&player.reloading<=0){
-    if(player.mag<=0){SFX.dry();player.fireCd=.25;
-      if(keys['r']!==true){player.reloading=RELOAD_T;SFX.reload();}}
+    if(player.mag<=0){SFX.dry();player.fireCd=.25;player.reloading=RELOAD_T;}
     else{player.mag--;shots++;player.fireCd=.13;muzzle=1;shake=Math.min(8,shake+1.6);
       const a=player.angle+(Math.random()-.5)*.05;
       bullets.push({x:player.x+Math.cos(a)*20,y:player.y+Math.sin(a)*20,vx:Math.cos(a)*640,vy:Math.sin(a)*640,life:1.1});
       SFX.shoot();
       burst(player.x+Math.cos(a)*22,player.y+Math.sin(a)*22,2,'#ffe9a8',120);
       if(player.mag===0){player.reloading=RELOAD_T;setTimeout(()=>SFX.reload(),80);}}
   }
   // (R reload handled in keydown; auto-reload on empty mag below)
   // bullets
   for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;
     if(b.life<=0||b.x<ARENA.x||b.x>ARENA.x+ARENA.w||b.y<ARENA.y||b.y>ARENA.y+ARENA.h){bullets.splice(i,1);continue;}
     for(let j=enemies.length-1;j>=0;j--){const e=enemies[j];
       if(Math.hypot(b.x-e.x,b.y-e.y)<e.r+3){
         bullets.splice(i,1);
         e.hp-=34;e.hitT=1; // visible hit flash
         const ka=Math.atan2(b.vy,b.vx);e.kbx+=Math.cos(ka)*160;e.kby+=Math.sin(ka)*160; // knockback
         burst(b.x,b.y,6,'#fff2c0',240);SFX.hit();
         addFloat(e.x,e.y-e.r-8,'-34','hit');
         if(e.hp<=0){enemies.splice(j,1);kills++;burst(e.x,e.y,18,e.col,300);burst(e.x,e.y,8,'#ffffff',200);
           SFX.kill();shake=Math.min(12,shake+4);addFloat(e.x,e.y,'+'+e.score,'kill');
           if(Math.random()<.3)pickups.push({x:e.x,y:e.y,t:0,type:'med'});
           if(kills>=12&&spawnQueue.length===0&&enemies.length===0)gameOver(true);
         }
         break;
       }}}
   // enemies
   for(const e of enemies){
     e.wob+=dt*5;e.hitT=Math.max(0,e.hitT-dt*5);e.atkCd-=dt;
     const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;
     const wob=Math.sin(e.wob)*20;
     const nx=dx/d,ny=dy/d;
     e.vx=(nx*e.speed-wob*ny*.4)+e.kbx;e.vy=(ny*e.speed+wob*nx*.4)+e.kby;
     e.kbx*=Math.pow(.001,dt);e.kby*=Math.pow(.001,dt);
     e.x+=e.vx*dt;e.y+=e.vy*dt;
     e.x=Math.min(ARENA.x+ARENA.w-e.r,Math.max(ARENA.x+e.r,e.x));
     e.y=Math.min(ARENA.y+ARENA.h-e.r,Math.max(ARENA.y+e.r,e.y));
     if(d<e.r+player.r+4&&e.atkCd<=0){e.atkCd=.8;damagePlayer(e.dmg);}
   }
   // particles / floaters / pickups
   for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.t+=dt;if(p.t>p.life){parts.splice(i,1);continue;}
     p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy*=.98;}
   for(let i=floaters.length-1;i>=0;i--){const f=floaters[i];f.t+=dt;f.y-=34*dt;if(f.t>1)floaters.splice(i,1);}
   for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.t+=dt;
     if(Math.hypot(p.x-player.x,p.y-player.y)<22){pickups.splice(i,1);
       player.hp=Math.min(player.maxHp,player.hp+25);SFX.pickup();addFloat(player.x,player.y-22,'+25 HP','heal');
       burst(player.x,player.y,10,'#9ff5c3',180);}
     else if(p.t>12)pickups.splice(i,1);}
   // HUD
   hpFill.style.width=(player.hp)+'%';hpFill.classList.toggle('low',player.hp<=35);
   hpText.textContent=`${Math.ceil(player.hp)} HP${player.inv>0?' — HIT!':''}`;
   ammoFill.style.width=(player.mag/MAG*100)+'%';
   ammoText.textContent=player.reloading>0?'— RELOADING… —':`${player.mag} / ∞ — [R] RELOAD`;
   foeText.textContent=`${12-kills}`;
 }


 /* ---------- render ---------- */
 function render(){
   ctx.save();
   if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);
   // bg
   ctx.fillStyle='#0f1512';ctx.fillRect(-20,-20,W+40,H+40);
   // grid
   ctx.strokeStyle='#1b2620';ctx.lineWidth=1;ctx.beginPath();
   for(let x=0;x<=W;x+=40){ctx.moveTo(x,0);ctx.lineTo(x,H);}
   for(let y=0;y<=H;y+=40){ctx.moveTo(0,y);ctx.lineTo(W,y);}
   ctx.stroke();
   // arena
   ctx.fillStyle='#121815';ctx.fillRect(ARENA.x,ARENA.y,ARENA.w,ARENA.h);
   ctx.strokeStyle='#33463b';ctx.lineWidth=2;ctx.strokeRect(ARENA.x,ARENA.y,ARENA.w,ARENA.h);
   ctx.strokeStyle='#9ff5c322';ctx.lineWidth=6;ctx.strokeRect(ARENA.x-4,ARENA.y-4,ARENA.w+8,ARENA.h+8);
   // center pad objective
   ctx.save();ctx.setLineDash([8,8]);ctx.strokeStyle='#5d8a71';ctx.lineWidth=1.5;
   ctx.beginPath();ctx.arc(W/2,H/2+80,44,0,6.29);ctx.stroke();ctx.restore();
   ctx.fillStyle='#5d8a7155';ctx.font='10px Consolas,monospace';ctx.textAlign='center';
   ctx.fillText('— HOLD PAD // DUSTWALL —',W/2,H/2+84);
   // corner ticks
   ctx.fillStyle='#9ff5c3';
   [[ARENA.x,ARENA.y],[ARENA.x+ARENA.w,ARENA.y],[ARENA.x,ARENA.y+ARENA.h],[ARENA.x+ARENA.w,ARENA.y+ARENA.h]].forEach(([x,y])=>{
     ctx.fillRect(x-4,y-4,8,8);});
   // pickups
   for(const p of pickups){const bob=Math.sin(p.t*5)*3;
     ctx.fillStyle='#0d2b1a';ctx.strokeStyle='#9ff5c3';ctx.lineWidth=2;
     ctx.beginPath();ctx.arc(p.x,p.y+bob,9,0,6.29);ctx.fill();ctx.stroke();
     ctx.fillStyle='#9ff5c3';ctx.fillRect(p.x-2,p.y+bob-5,4,10);ctx.fillRect(p.x-5,p.y+bob-2,10,4);}
   // enemies
   for(const e of enemies){
     ctx.save();ctx.translate(e.x,e.y);
     ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(2,4,e.r,e.r*.6,0,0,6.29);ctx.fill();
     const ang=Math.atan2(player?player.y-e.y:0,player?player.x-e.x:0);
     ctx.rotate(ang);
     const flash=e.hitT>0;
     ctx.fillStyle=flash?'#ffffff':e.col;
     ctx.strokeStyle=flash?'#ffffff':'#0a0d0c';ctx.lineWidth=2;
     if(e.type==='jackal'){ // diamond scout
       ctx.beginPath();ctx.moveTo(12,0);ctx.lineTo(0,8);ctx.lineTo(-12,0);ctx.lineTo(0,-8);ctx.closePath();ctx.fill();ctx.stroke();
