const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1100,900', '--autoplay-policy=no-user-gesture-required'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1100, height: 900 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://127.0.0.1:8099/index.html', { waitUntil: 'networkidle0' });
  await new Promise(r => setTimeout(r, 800));
  await page.screenshot({ path: '/tmp/opencode/verify/shot-menu.png' });

  // start game via button
  await page.click('#btnStart');
  await new Promise(r => setTimeout(r, 2500));
  // move + aim + fire
  await page.keyboard.down('d');
  await page.mouse.move(700, 300);
  await page.mouse.down();
  await new Promise(r => setTimeout(r, 1500));
  await page.keyboard.up('d');
  await page.keyboard.down('w');
  await new Promise(r => setTimeout(r, 1200));
  await page.keyboard.up('w');
  await page.screenshot({ path: '/tmp/opencode/verify/shot-play.png' });
  const st1 = await page.evaluate(() => ({
    state: window.IRONLINE.state, kills: window.IRONLINE.kills,
    foe: document.getElementById('foeText').textContent,
    hp: document.getElementById('hpText').textContent,
    ammo: document.getElementById('ammoText').textContent,
  }));
  await page.mouse.up();
  // reload key
  await page.keyboard.press('r');
  await new Promise(r => setTimeout(r, 300));
  const ammoAfterR = await page.evaluate(() => document.getElementById('ammoText').textContent);
  // pause
  await page.keyboard.press('p');
  await new Promise(r => setTimeout(r, 300));
  const paused = await page.evaluate(() => window.IRONLINE.state);
  await page.screenshot({ path: '/tmp/opencode/verify/shot-pause.png' });
  await page.keyboard.press('p');

  // victory
  await page.evaluate(() => window.IRONLINE.win());
  await new Promise(r => setTimeout(r, 1200));
  await page.screenshot({ path: '/tmp/opencode/verify/shot-win.png' });
  const winVisible = await page.evaluate(() => ({
    state: window.IRONLINE.state,
    overlay: document.getElementById('overlay').classList.contains('show'),
    title: document.getElementById('ovTitle').textContent,
  }));
  // restart via R key from win
  await page.keyboard.press('r');
  await new Promise(r => setTimeout(r, 800));
  const afterRestart = await page.evaluate(() => ({
    state: window.IRONLINE.state,
    overlay: document.getElementById('overlay').classList.contains('show'),
    foe: document.getElementById('foeText').textContent,
  }));
  // defeat
  await page.evaluate(() => window.IRONLINE.lose());
  await new Promise(r => setTimeout(r, 1500));
  await page.screenshot({ path: '/tmp/opencode/verify/shot-lose.png' });
  const loseVisible = await page.evaluate(() => ({
    state: window.IRONLINE.state,
    overlay: document.getElementById('overlay').classList.contains('show'),
    title: document.getElementById('ovTitle').textContent,
  }));
  // restart via button
  await page.click('#btnRestart');
  await new Promise(r => setTimeout(r, 800));
  const afterBtn = await page.evaluate(() => ({
    state: window.IRONLINE.state,
    overlay: document.getElementById('overlay').classList.contains('show'),
  }));

  console.log(JSON.stringify({ st1, ammoAfterR, paused, winVisible, afterRestart, loseVisible, afterBtn, errors }, null, 1));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

